from typing import Any
import json
import fastmcp
import httpx


def create_openapi_mcp_server(
    spec: dict,
    client: httpx.AsyncClient,
    server_name: str = "openapi-server",
) -> fastmcp.Server:
    """
    Create an MCP server from an OpenAPI 3.0 specification.

    Args:
        spec: OpenAPI 3.0 spec as a Python dict
        client: Configured httpx.AsyncClient with base URL set
        server_name: Name for the MCP server

    Returns:
        Configured fastmcp.Server ready to be started
    """
    server = fastmcp.Server(server_name)

    paths = spec.get("paths", {})

    for path, path_item in paths.items():
        for method, operation in path_item.items():
            if method.lower() not in ["get", "post", "put", "delete", "patch", "head", "options"]:
                continue

            operation_id = operation.get("operationId", f"{method}_{path.replace('/', '_')}")
            summary = operation.get("summary", "")

            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody", {})

            param_props = {}
            required_params = []

            for param in parameters:
                param_name = param.get("name")
                param_schema = param.get("schema", {})
                param_required = param.get("required", False)
                param_type = param_schema.get("type", "string")

                json_type = "string"
                if param_type == "integer":
                    json_type = "number"
                elif param_type == "boolean":
                    json_type = "boolean"
                elif param_type == "number":
                    json_type = "number"

                param_props[param_name] = {
                    "type": json_type,
                    "description": param.get("description", "")
                }

                if param_required:
                    required_params.append(param_name)

            if request_body:
                body_required = request_body.get("required", False)
                param_props["body"] = {
                    "type": "object",
                    "description": "Request body"
                }
                if body_required:
                    required_params.append("body")

            tool_input_schema = {
                "type": "object",
                "properties": param_props,
                "required": required_params
            }

            async def make_request(
                operation_path: str = path,
                operation_method: str = method.lower(),
                operation_params: dict = parameter,
                operation_body: dict = request_body,
                **kwargs: Any
            ) -> dict:
                """Execute the API operation."""
                url = operation_path
                headers = {}
                query_params = {}
                body_data = None

                for param in parameters:
                    param_name = param.get("name")
                    param_in = param.get("in", "query")

                    if param_name in kwargs:
                        if param_in == "query":
                            query_params[param_name] = kwargs[param_name]
                        elif param_in == "path":
                            url = url.replace(f"{{{param_name}}}", str(kwargs[param_name]))
                        elif param_in == "header":
                            headers[param_name] = kwargs[param_name]

                if "body" in kwargs and operation_body:
                    body_data = kwargs["body"]

                response = await client.request(
                    operation_method,
                    url,
                    params=query_params if query_params else None,
                    json=body_data if body_data else None,
                    headers=headers if headers else None
                )

                return {
                    "status": response.status_code,
                    "body": response.json() if response.text else None,
                    "headers": dict(response.headers)
                }

            server.add_tool(
                make_request,
                name=operation_id,
                description=summary or f"{method.upper()} {path}",
                inputSchema=tool_input_schema
            )

    return server


if __name__ == "__main__":
    example_spec = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0.0"},
        "paths": {
            "/users/{user_id}": {
                "get": {
                    "operationId": "getUser",
                    "summary": "Get a user by ID",
                    "parameters": [
                        {
                            "name": "user_id",
                            "in": "path",
                            "required": True,
                            "schema": {"type": "string"}
                        }
                    ]
                }
            }
        }
    }

    async def main():
        async with httpx.AsyncClient(base_url="https://api.example.com") as client:
            server = create_openapi_mcp_server(example_spec, client)
            await server.run_stdio()

    import asyncio
    asyncio.run(main())

